int flush_key_notification_policy(const struct km_event *c) {
    struct sk_buff *skb;
    struct pfkey_msg *hdr;
    int err = 0;

    skb = alloc_skb(PFKEY_SOCKET_BUFFER_SIZE, GFP_KERNEL);
    if (!skb) {
        return -ENOBUFS;
    }

    skb_put(skb, sizeof(*hdr));
    hdr = skb->data;
    hdr->msg_version = PF_KEY_V2;
    hdr->msg_type = SADB_X_SPDINFO_FLUSH;
    hdr->msg_satype = 0;
    hdr->msg_len = sizeof(*hdr) / 8;

    NETLINK_CB(skb).portid = c->port_id;
    NETLINK_CB(skb).dst_group = 0; /* No group - unicast */

    err = netlink_broadcast(c->netlink, skb, 0, 0, GFP_KERNEL);
    if (err < 0) {
        kfree_skb(skb);
        return err;
    }

    return 0;
}

